// Package schema exposes the merged osquery + Fleet table schema to Go
// consumers (e.g. cmd/fleet-mcp) so they embed the canonical file instead
// of carrying a copy. It is its own dependency-free module so consumers
// don't have to pin the whole fleet/v4 module graph.
package schema

import _ "embed"

// OsqueryFleetSchemaJSON is the content of osquery_fleet_schema.json, the
// file generated by `sails run generate-merged-schema` (see README.md) and
// rendered at https://fleetdm.com/tables.
//
//go:embed osquery_fleet_schema.json
var OsqueryFleetSchemaJSON []byte
